// Modified remember function to use voucherManager.js
function remember() {
    var usernameInput = document.login.querySelector("input[username-field]");
    var speedSelect = document.login.querySelector("#speed"); // Ensure this ID is correct for speed select

    if (usernameInput && usernameInput.value && speedSelect && speedSelect.value) {
        var username = usernameInput.value;
        var speedValue = speedSelect.value;

        // Instead of setLoginCardCookie, call saveVoucher from voucherManager.js
        if (typeof saveVoucher === 'function') {
            saveVoucher(username, speedValue);
        } else {
            console.error('saveVoucher function is not defined. Make sure voucherManager.js is loaded.');
        }
    } else {
        console.warn('Could not save voucher: username or speed field not found or empty.');
    }
}

