// Modified clearCookies to clear localStorage vouchers as well, or primarily focus on that.
// The original clearCookies was tied to a button [clear-hot-cookie].
// This button might be repurposed or a new one created for clearing localStorage.
function clearHotspotStorage() {
    // Clear old cookies just in case they exist from previous versions
    var oldCookieKeys = ["username", "password", "speed"];
    for (var i = 0; i < oldCookieKeys.length; i++) {
        document.cookie = oldCookieKeys[i] + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/";
    }
    console.log('Old hotspot cookies cleared (if any).');

    // Clear new localStorage vouchers
    if (typeof clearAllSavedVouchers === 'function') {
        clearAllSavedVouchers();
    } else {
        console.error('clearAllSavedVouchers function is not defined.');
    }
}

