// Modify registerClearCookieButton to use clearHotspotStorage
// Ensure the button with attribute [clear-hot-cookie] is still relevant or update the selector.
function registerClearStorageButton() {
    var clearButton = document.querySelector("[clear-hot-cookie]"); // Or a new attribute e.g., [clear-saved-vouchers]
    if (clearButton) {
        clearButton.addEventListener("click", function(event) {
            // Optional: Ask for confirmation before clearing
            // if (confirm("Are you sure you want to delete all saved login cards?")) {
            //     clearHotspotStorage();
            //     // Optionally, refresh the voucher dropdown if it's visible
            //     if (typeof populateVoucherDropdown === 'function') {
            //         populateVoucherDropdown();
            //     }
            // }
            clearHotspotStorage(); // For now, clear directly
            // If a dropdown exists and is populated, it should be cleared/updated.
            // This function (populateVoucherDropdown) will be created in the next step.
             if (typeof populateVoucherDropdown === 'function') {
                 populateVoucherDropdown();
             }
        });
    }
}

// Ensure this runs after the DOM is loaded.
document.addEventListener("DOMContentLoaded", function() {
    registerClearStorageButton();
}, !1);

